-- Views
CREATE OR REPLACE VIEW gold."vw_barangay_yield_distance" AS
 SELECT dg.geography_key,
    dg.barangay_name,
    dg.city,
    dg.province,
    dg.distance_km_from_campus,
    count(DISTINCT fe.student_key) AS enrollment_yield
   FROM (dim_geography dg
     JOIN fact_enrollment fe ON ((fe.geography_key = dg.geography_key)))
  WHERE ((dg.is_foreign = false) AND (dg.distance_km_from_campus IS NOT NULL))
  GROUP BY dg.geography_key, dg.barangay_name, dg.city, dg.province, dg.distance_km_from_campus;;

